def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        base = DAILY_SALARY * 0.25
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    bob_like = []
    cindy_like = []
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 120:
                cindy_like.append(float(bid))
            else:
                bob_like.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    bob_anchor = max(bob_like) if bob_like else (max(prev_bids) if prev_bids else 55.0)

    alive_count = len(alive)
    tight_supply = supply <= WATER_REQ * alive_count
    very_tight = supply <= WATER_REQ * max(1, alive_count - 1)

    urgency = 0
    if hp <= 3:
        urgency += 2
    elif hp <= 5:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1
    if very_tight:
        urgency += 2
    elif tight_supply:
        urgency += 1
    if day >= 8:
        urgency += 1

    if urgency >= 5:
        bid = max(DAILY_SALARY * 0.95, bob_anchor + 8.0)
    elif urgency >= 3:
        bid = max(DAILY_SALARY * 0.72, bob_anchor + 2.5)
    elif urgency >= 1:
        if highest_prev >= 120:
            bid = DAILY_SALARY * 0.42
        else:
            bid = max(DAILY_SALARY * 0.5, bob_anchor)
    else:
        if highest_prev >= 120:
            bid = DAILY_SALARY * 0.22
        else:
            bid = DAILY_SALARY * 0.35

    if budget < DAILY_SALARY * 2 and urgency <= 2:
        bid = min(bid, DAILY_SALARY * 0.4)
    if budget < DAILY_SALARY and urgency >= 3:
        bid = max(min(budget, DAILY_SALARY * 0.9), budget * 0.85)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((k, o))

    # If no one alive, conserve budget
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    cindy_bid = None
    other_bids = []
    for agent_id, o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = float(prev.get('bid'))
            if agent_id == 'Cindy':
                cindy_bid = b
            else:
                other_bids.append(b)

    # Determine pressure level from Cindy (dominant survivor)
    pressure = 0.0
    if cindy_bid is not None:
        pressure = cindy_bid
    elif other_bids:
        pressure = max(other_bids)

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Supply-based aggressiveness: medium scenario implies contesting at moderate-high supply.
    # Map supply to a multiplier in [0.9, 1.2]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_mult = 1.0
    else:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        supply_mult = 0.9 + 0.3 * t

    # If Cindy bid extremely high yesterday, match her tier but slightly under to avoid overspending.
    # If Cindy bid low/unknown, use a baseline that targets survival.
    if cindy_bid is not None:
        if cindy_bid >= 120.0:
            base = 0.78 * cindy_bid
        elif cindy_bid >= 80.0:
            base = 0.65 * cindy_bid
        else:
            base = 0.55 * cindy_bid
    else:
        # No Cindy info: use others' max as proxy
        if other_bids:
            mx = max(other_bids)
            base = 0.6 * mx
        else:
            base = DAILY_SALARY * 0.55

    # Survival urgency adjustment
    if hp <= 2.0:
        base *= 1.25
    elif hp <= 4.0:
        base *= 1.10
    else:
        base *= 1.00

    # Apply supply multiplier
    base *= supply_mult

    # Cap by budget and also avoid going above a reasonable fraction of budget
    # (prevents bankrupting if contest is lost)
    safe_cap = budget

    # If budget is low, bid proportionally higher to secure at least one unit of water
    if budget <= DAILY_SALARY * 0.5:
        base = max(base, DAILY_SALARY * 0.35)

    bid = float(min(safe_cap, base))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    # Also avoid bidding trivially low when supply is ample
    if supply >= 20.0 and bid < DAILY_SALARY * 0.25:
        bid = float(min(safe_cap, DAILY_SALARY * 0.25))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # CRITICAL HEALTH: If HP is very low, bid aggressively to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # If I haven't received water recently, I need to increase my chances
    if my_status['no_water_days'] > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8: # If opponents are very aggressive
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        elif highest_prev_bid > 0:
            return min(my_status['budget'], highest_prev_bid + 2.0)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.75)

    current_supply = day_context['supply']

    # If supply is very tight (only enough for one full requirement or slightly more)
    if current_supply <= WATER_REQ + 4: # Covers supply 15-17 for WATER_REQ=13
        if my_status['hp'] <= 4: # Moderate health concern, be more aggressive
            return min(my_status['budget'], DAILY_SALARY * 0.8)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            return min(my_status['budget'], highest_prev_bid + 1.5)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.7)

    # General bidding based on opponent pressure and my health
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 3:
            return min(my_status['budget'], DAILY_SALARY * 0.6)
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        return min(my_status['budget'], highest_prev_bid + 1.0)

    # Default bid: No strong pressure from opponents or my health
    if day_context['day'] >= EPISODE_DAYS - 2:
        return min(my_status['budget'], DAILY_SALARY * 0.7)
    else:
        return min(my_status['budget'], DAILY_SALARY * 0.55)

